int sys_auth_passwd ( struct ssh * ssh , const char * password ) { Authctxt * ctxt = ssh -> authctxt ; char * authmsg = NULL , * msg = NULL , * name = ctxt -> pw -> pw_name ; int r , authsuccess = 0 , expired , reenter , result ; { result = authenticate ( ( char * ) name , ( char * ) password , & reenter , & authmsg ) ; aix_remove_embedded_newlines ( authmsg , NULL ) ; debug3 ( "AIX/authenticate result %d, authmsg %.100s" , result , authmsg ) ; } reenter ; if ( ! aix_valid_authentications ( name ) ) { result = - 1 ; } if ( result == 0 ) { authsuccess = 1 ; aix_setauthdb ( name ) ; expired = passwdexpired ( name , & msg ) ; if ( msg && * msg ) { if ( ( r = sshbuf_put ( ctxt -> loginmsg , msg , strlen ( msg ) ) ) != 0 ) { fatal ( "%s: buffer error: %s" , __func__ , ssh_err ( r ) ) ; } aix_remove_embedded_newlines ( msg ) ; } debug3 ( "AIX/passwdexpired returned %d msg %.100s" , expired , msg ) ; switch ( expired ) { case 0 : break ; case 1 : ctxt -> force_pwchange = 1 ; break ; default : logit ( "Password can't be changed for user %s: %.100s" , name , msg ) ; free ( msg ) ; authsuccess = 0 ; } aix_restoreauthdb ( ) ; } free ( authmsg ) ; return authsuccess ; } 